using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a. Default resolver knows about Person → should succeed
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// 2b. Options with a custom resolver that only handles Person.
//     Querying for int should return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
    Console.WriteLine($"TryGetTypeInfo<int> succeeded → {intInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<int> returned false (resolver doesn't handle int)");

// --- types ---

public record Person(string Name, int Age);

/// A resolver that only provides metadata for Person.
file sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return JsonMetadataServices.CreateObjectInfo<Person>(options, new JsonObjectInfoValues<Person>());

        return null; // unknown type
    }
}

